/// 平方分割による区間和
///
/// できること
///  - 1点更新
///  - 1点取得
///  - 区間和取得
///
/// セグ木でできるけど練習用＾
#[derive(Clone, Debug)]
pub struct SqrtRangeSum {
    /// 元配列と平方分割の添字管理
    array: SqrtArray<i64>,

    // block_sum[block_id] = そのブロックの合計値
    block_sum: Vec<i64>,
} // end of struct SqrtRangeSum

impl SqrtRangeSum {
    // Vec<i64> から構築
    pub fn new(values: Vec<i64>) -> Self {
        let array = SqrtArray::new(values);
        return Self::from_array(array);
    } // end of constructor

    /// block_sizeを指定して構築
    pub fn with_block_size(values: Vec<i64>, block_size: usize) -> Self {
        let array = SqrtArray::with_block_size(values, block_size);
        return Self::from_array(array);
    } // end of constructor

    /// SqrtArray<i64>から構築
    fn from_array(array: SqrtArray<i64>) -> Self {
        let block_count = array.block_count();
        let mut this = Self {
            array,
            block_sum: vec![0_i64; block_count],
        };

        for block_id in 0..block_count {
            this.rebuild(block_id);
        }
        return this;
    } // end of constructor

    /// 指定ブロックの合計を作り直す
    fn rebuild(&mut self, block_id: usize) {
        let mut sum = 0_i64;

        for value in self.array.block_slice(block_id) {
            sum += *value;
        }
        self.block_sum[block_id] = sum;
    } // end of method

    /// 要素数を返す
    #[inline(always)]
    pub fn len(&self) -> usize {
        return self.array.len();
    } // end of method

    /// 空かを返す
    #[inline(always)]
    pub fn is_empty(&self) -> bool {
        return self.array.is_empty();
    } // end of method

    /// 1要素を取得する
    #[inline(always)]
    pub fn get(&self, index: usize) -> i64 {
        return *self.array.get(index);
    } // end of method

    /// 1要素を書き換える
    #[inline(always)]
    pub fn set(&mut self, index: usize, value: i64) {
        let block_id = self.array.block_id(index);

        self.array.set(index, value);
        self.rebuild(block_id);
    } // end of method

    /// 区間 [l, r) の合計を返す
    #[inline(always)]
    pub fn range_sum(&self, l: usize, r: usize) -> i64 {
        let sqrt_range = self.array.split_range(l, r);
        let mut answer = 0_i64;

        for index in sqrt_range.head_indexes {
            answer += *self.array.get(index);
        }
        for block_id in sqrt_range.body_blocks {
            answer += self.block_sum[block_id];
        }
        for index in sqrt_range.tail_indexes {
            answer += *self.array.get(index);
        }
        return answer;
    } // end of method
} // end of impl SqrtRangeSum

/// 平方分割による区間最小
///
/// できること
///  - 1点更新
///  - 1点取得
///  - 区間最小値取得
///
/// 空区間のminは定義しにくいので, range_minは l < r を前提に
#[derive(Clone, Debug)]
pub struct SqrtRangeMin {
    /// 元配列と平方分割の添字管理
    array: SqrtArray<i64>,

    /// block_min[block_id] = そのブロックの最小値
    block_min: Vec<i64>,
} // end of struct SqrtRangeMin

impl SqrtRangeMin {
    /// Vec<i64>から構築する
    pub fn new(values: Vec<i64>) -> Self {
        let array = SqrtArray::new(values);
        return Self::from_array(array);
    } // end of constructor

    /// block_sizeを指定して構築
    pub fn with_block_size(values: Vec<i64>, block_size: usize) -> Self {
        let array = SqrtArray::with_block_size(values, block_size);
        return Self::from_array(array);
    } // end of constructor

    /// SqrtArray<i64>から構築する
    fn from_array(array: SqrtArray<i64>) -> Self {
        let block_count = array.block_count();

        let mut this = Self {
            array,
            block_min: vec![i64::MAX; block_count],
        };

        for block_id in 0..block_count {
            this.rebuild(block_id);
        }
        return this;
    } // end of constructor

    /// 指定ブロックの最小値を作り直す
    fn rebuild(&mut self, block_id: usize) {
        let mut minimum = i64::MAX;

        for value in self.array.block_slice(block_id) {
            minimum = std::cmp::min(minimum, *value);
        }
        self.block_min[block_id] = minimum;
    } // end of method

    /// 要素数を返す
    #[inline(always)]
    pub fn len(&self) -> usize {
        return self.array.len();
    } // end of method

    /// 空かを返す
    #[inline(always)]
    pub fn is_empty(&self) -> bool {
        return self.array.is_empty();
    } // end of method

    /// 1要素を取得する
    #[inline(always)]
    pub fn get(&self, index: usize) -> i64 {
        return *self.array.get(index);
    } // end of method

    /// 1要素を書き換える
    #[inline(always)]
    pub fn set(&mut self, index: usize, value: i64) {
        let block_id = self.array.block_id(index);

        self.array.set(index, value);
        self.rebuild(block_id);
    } // end of method

    /// 区間 [l, r) の最小値を返す
    /// l == r の空区間は不可
    pub fn range_min(&self, l: usize, r: usize) -> i64 {
        debug_assert!(l < r, "range_min requires non empty range");

        let sqrt_range = self.array.split_range(l, r);
        let mut answer = i64::MAX;

        for index in sqrt_range.head_indexes {
            answer = std::cmp::min(answer, *self.array.get(index));
        }
        for block_id in sqrt_range.body_blocks {
            answer = std::cmp::min(answer, self.block_min[block_id]);
        }
        for index in sqrt_range.tail_indexes {
            answer = std::cmp::min(answer, *self.array.get(index));
        }
        return answer;
    } // end of method
} // end of SqrtRangeMin

/// 遅延加算つき平方分割による区間和
///
/// できること
///  - 区間加算
///  - 1点取得
///  - 1点代入
///  - 区間和取得
///
/// 内部表現
///  - values[index] → lazyを除いた値
///  - lazy[block_id] → ブロック全体に未反映の加算値
///  - block_sum[block_id] → lazyも含んだ実際の合計値
#[derive(Clone, Debug)]
pub struct LazyAddSqrtRangeSum {
    /// 平方分割の添字管理
    bucket: SqrtBucket,

    /// lazyを除いた元配列
    values: Vec<i64>,

    /// ブロックごとの実際の合計値
    block_sum: Vec<i64>,

    /// ブロックごとの遅延加算値
    lazy: Vec<i64>,
} // end of struct LazyAddSqrtRangeSum

impl LazyAddSqrtRangeSum {
    /// Vec<i64> から構築する
    pub fn new(values: Vec<i64>) -> Self {
        let n = values.len();
        let bucket = SqrtBucket::new(n);
        return Self::from_bucket_and_values(bucket, values);
    } // end of constructor

    /// block_sizeを指定して構築
    pub fn with_block_size(values: Vec<i64>, block_size: usize) -> Self {
        let n = values.len();
        let bucket = SqrtBucket::with_block_size(n, block_size);

        return Self::from_bucket_and_values(bucket, values);
    } // end of constructor

    /// SqrtBucketとvaluesから構築する
    fn from_bucket_and_values(bucket: SqrtBucket, values: Vec<i64>) -> Self {
        let block_count = bucket.block_count();

        let mut this = Self {
            bucket,
            values,
            block_sum: vec![0_i64; block_count],
            lazy: vec![0_i64; block_count],
        };

        for block_id in 0..block_count {
            this.rebuild(block_id);
        }
        return this;
    } // end of constructor

    /// 指定ブロックの合計値を作り直す
    /// lazy[block_id]が0の状態で呼ぶ
    #[inline(always)]
    fn rebuild(&mut self, block_id: usize) {
        let mut sum = 0_i64;
        for index in self.bucket.block_range(block_id) {
            sum += self.values[index];
        }
        self.block_sum[block_id] = sum;
    } // end of method

    /// 指定ブロックのlazyをvaluesに反映する
    #[inline(always)]
    fn push(&mut self, block_id: usize) {
        let add_value = self.lazy[block_id];
        if add_value == 0 {
            return;
        }

        for index in self.bucket.block_range(block_id) {
            self.values[index] += add_value;
        }

        self.lazy[block_id] = 0;
        self.rebuild(block_id);
    } // end of method

    /// 要素数を返す
    #[inline(always)]
    pub fn len(&self) -> usize {
        return self.values.len();
    } // end of method

    /// 空かを返す
    #[inline(always)]
    pub fn is_empty(&self) -> bool {
        return self.values.is_empty();
    } // end of method

    /// 1要素を取得する
    #[inline(always)]
    pub fn get(&self, index: usize) -> i64 {
        let block_id: usize = self.bucket.block_id(index);
        return self.values[index] + self.lazy[block_id];
    } // end of method

    /// 1要素を実際の値として代入
    #[inline(always)]
    pub fn set(&mut self, index: usize, value: i64) {
        let block_id: usize = self.bucket.block_id(index);

        self.push(block_id);
        self.values[index] = value;
        self.rebuild(block_id);
    } // end of method

    /// 区間 [l, r) にadd_valueを加算
    #[inline(always)]
    pub fn range_add(&mut self, l: usize, r: usize, add_value: i64) {
        let sqrt_range = self.bucket.split_range(l, r);

        if !sqrt_range.head_indexes.is_empty() {
            let block_id: usize = self.bucket.block_id(sqrt_range.head_indexes.start);
            self.push(block_id);

            for index in sqrt_range.head_indexes {
                self.values[index] += add_value;
            }
            self.rebuild(block_id);
        }

        for block_id in sqrt_range.body_blocks {
            let block_len = self.bucket.block_len(block_id) as i64;

            self.lazy[block_id] += add_value;
            self.block_sum[block_id] += add_value * block_len;
        }

        if !sqrt_range.tail_indexes.is_empty() {
            let block_id: usize = self.bucket.block_id(sqrt_range.tail_indexes.start);
            self.push(block_id);

            for index in sqrt_range.tail_indexes {
                self.values[index] += add_value;
            }
            self.rebuild(block_id);
        }
    } // end of method

    /// 区間 [l, r) の合計を返す
    #[inline(always)]
    pub fn range_sum(&self, l: usize, r: usize) -> i64 {
        let sqrt_range = self.bucket.split_range(l, r);
        let mut answer = 0_i64;

        for index in sqrt_range.head_indexes {
            answer += self.get(index);
        }
        for block_id in sqrt_range.body_blocks {
            answer += self.block_sum[block_id];
        }
        for index in sqrt_range.tail_indexes {
            answer += self.get(index);
        }
        return answer;
    } // end of method
} // end of impl LazyAddSqrtRangeSum

/// 遅延加算 + ソート済みブロック + 累積和付き平方分割
///
/// できるこーと
///  - 区間加算
///  - 1点取得
///  - 1点代入
///  - 区間内で value < x の個数
///  - 区間内で value >= x の個数
///  - 区間内で value < x の合計
///  - 区間内で value >= x の合計
///  - 区間内の max(0, value) の合計
///
/// AtCoder Weekday Contest 104 E問題想定
#[derive(Clone, Debug)]
pub struct LazySortedSqrt {
    /// 平方分割の添字管理
    bucket: SqrtBucket,

    /// Lazyを除いた元配列
    values: Vec<i64>,

    /// ブロックごとの遅延加算値
    lazy: Vec<i64>,

    /// sorted_values[block_id] = ブロック内 values をソートした配列
    sorted_values: Vec<Vec<i64>>,

    /// prefix_sum[block_id][k] = sorted_values[block_id][0..k] の合計
    prefix_sum: Vec<Vec<i64>>,
} // end of struct LazySortedSqrt

impl LazySortedSqrt {
    /// Vec<i64>から構築する
    pub fn new(values: Vec<i64>) -> Self {
        let n = values.len();
        let bucket = SqrtBucket::new(n);

        return Self::from_bucket_and_values(bucket, values);
    } // end of constructor

    /// スライス&[i64]から構築
    pub fn from_slice(values: &[i64]) -> Self {
        return Self::new(values.to_vec());
    } // end of constructor

    /// block_sizeを指定して構築する
    pub fn with_block_size(values: Vec<i64>, block_size: usize) -> Self {
        let n = values.len();
        let bucket = SqrtBucket::with_block_size(n, block_size);

        return Self::from_bucket_and_values(bucket, values);
    } // end of constructor

    /// SqrtBucketとvaluesから構築する
    fn from_bucket_and_values(bucket: SqrtBucket, values: Vec<i64>) -> Self {
        let block_count = bucket.block_count();

        let mut this = Self {
            bucket,
            values,
            lazy: vec![0_i64; block_count],
            sorted_values: vec![Vec::<i64>::new(); block_count],
            prefix_sum: vec![Vec::<i64>::new(); block_count],
        };

        for block_id in 0..block_count {
            this.rebuild(block_id);
        }
        return this;
    } // end of constructor

    /// 指定ブロックのsorted_valuesとprefix_sumを作り直す
    #[inline(always)]
    fn rebuild(&mut self, block_id: usize) {
        let range = self.bucket.block_range(block_id);
        let mut sorted = Vec::<i64>::new();

        for index in range {
            sorted.push(self.values[index]);
        }
        sorted.sort_unstable();

        let mut prefix = vec![0_i64; sorted.len() + 1];
        for i in 0..sorted.len() {
            prefix[i + 1] = prefix[i] + sorted[i];
        }

        self.sorted_values[block_id] = sorted;
        self.prefix_sum[block_id] = prefix;
    } // end of method

    /// 指定ブロックのlazyをvaluesに反映する
    #[inline(always)]
    fn push(&mut self, block_id: usize) {
        let add_value = self.lazy[block_id];
        if add_value == 0 {
            return;
        }

        for index in self.bucket.block_range(block_id) {
            self.values[index] += add_value;
        }
        self.lazy[block_id] = 0;
        self.rebuild(block_id);
    } // end of method

    /// i64のソート済み配列に対するLowerBound
    /// targetはi128に
    ///  → x - lazy が i64の範囲を少し超える場合でも安全に比較可能
    #[inline(always)]
    fn lower_bound_i128(values: &[i64], target: i128) -> usize {
        let mut left = values.len();
        let mut right = 0_usize;

        while right < left {
            let mid = (right + left) / 2;
            if (values[mid] as i128) < target {
                right = mid + 1;
            } else {
                left = mid;
            }
        }
        return left;
    } // end of method

    /// 要素数を返す
    #[inline(always)]
    pub fn len(&self) -> usize {
        return self.values.len();
    } // end of method

    /// 空かを返す
    #[inline(always)]
    pub fn is_empty(&self) -> bool {
        return self.values.is_empty();
    } // end of method

    /// 1要素を取得する
    #[inline(always)]
    pub fn get(&self, index: usize) -> i64 {
        let block_id = self.bucket.block_id(index);
        return self.values[index] + self.lazy[block_id];
    } // end of method

    /// 1要素を実際の値として代入
    #[inline(always)]
    pub fn set(&mut self, index: usize, value: i64) {
        let block_id = self.bucket.block_id(index);

        self.push(block_id);
        self.values[index] = value;
        self.rebuild(block_id);
    } // end of method

    /// 区間 [l, r) にadd_valueを加算する
    pub fn range_add(&mut self, l: usize, r: usize, add_value: i64) {
        let sqrt_range = self.bucket.split_range(l, r);

        if !sqrt_range.head_indexes.is_empty() {
            let block_id = self.bucket.block_id(sqrt_range.head_indexes.start);
            self.push(block_id);

            for index in sqrt_range.head_indexes {
                self.values[index] += add_value;
            }
            self.rebuild(block_id);
        }

        for block_id in sqrt_range.body_blocks {
            self.lazy[block_id] += add_value;
        }

        if !sqrt_range.tail_indexes.is_empty() {
            let block_id = self.bucket.block_id(sqrt_range.tail_indexes.start);
            self.push(block_id);

            for index in sqrt_range.tail_indexes {
                self.values[index] += add_value;
            }
            self.rebuild(block_id);
        }
    } // end of method

    /// まるごとブロックについて value < x の値を返す
    #[inline(always)]
    fn block_count_less_than(&self, block_id: usize, x: i64) -> usize {
        let target = (x as i128) - (self.lazy[block_id] as i128);
        return Self::lower_bound_i128(&self.sorted_values[block_id], target);
    } // end of method

    /// まるごとブロックについて values < x の合計を返す
    #[inline(always)]
    fn block_sum_less_than(&self, block_id: usize, x: i64) -> i64 {
        let count = self.block_count_less_than(block_id, x);
        let raw_sum = self.prefix_sum[block_id][count];
        return raw_sum + self.lazy[block_id] * (count as i64);
    } // end of method

    /// まるごとブロックについて value >= x の合計を返す
    #[inline(always)]
    fn block_sum_greater_equal(&self, block_id: usize, x: i64) -> i64 {
        let count_less = self.block_count_less_than(block_id, x);
        let block_len = self.sorted_values[block_id].len();

        let raw_sum = self.prefix_sum[block_id][block_len] - self.prefix_sum[block_id][count_less];
        let count_greater_equal = block_len - count_less;

        return raw_sum + self.lazy[block_id] * (count_greater_equal as i64);
    } // end of method

    /// 区間 [l, r) で value < x の個数を返す
    pub fn count_less_than(&self, l: usize, r: usize, x: i64) -> usize {
        let sqrt_range = self.bucket.split_range(l, r);
        let mut answer = 0_usize;

        for index in sqrt_range.head_indexes {
            if self.get(index) < x {
                answer += 1;
            }
        }

        for block_id in sqrt_range.body_blocks {
            answer += self.block_count_less_than(block_id, x);
        }

        for index in sqrt_range.tail_indexes {
            if self.get(index) < x {
                answer += 1;
            }
        }
        return answer;
    } // end of method

    /// 区間 [l, r) でvalue >= xの個数を返す
    ///  value >= x の個数は, 区間長 - value < x の個数で求める
    #[inline(always)]
    pub fn count_greater_equal(&self, l: usize, r: usize, x: i64) -> usize {
        let range_len = r - l;
        let count_less = self.count_less_than(l, r, x);
        return range_len - count_less;
    } // end of method

    /// 区間 [l, r) でvalue < x の合計を返す
    #[inline(always)]
    pub fn sum_less_than(&self, l: usize, r: usize, x: i64) -> i64 {
        let sqrt_range = self.bucket.split_range(l, r);
        let mut answer = 0_i64;

        for index in sqrt_range.head_indexes {
            let value = self.get(index);
            if value < x {
                answer += value;
            }
        }

        for block_id in sqrt_range.body_blocks {
            answer += self.block_sum_less_than(block_id, x);
        }

        for index in sqrt_range.tail_indexes {
            let value = self.get(index);
            if value < x {
                answer += value;
            }
        }
        return answer;
    } // end of method

    /// 区間 [l, r) で value >= xの合計を返す
    pub fn sum_greater_equal(&self, l: usize, r: usize, x: i64) -> i64 {
        let sqrt_range = self.bucket.split_range(l, r);
        let mut answer = 0_i64;

        for index in sqrt_range.head_indexes {
            let value = self.get(index);
            if value >= x {
                answer += value;
            }
        }

        for block_id in sqrt_range.body_blocks {
            answer += self.block_sum_greater_equal(block_id, x);
        }

        for index in sqrt_range.tail_indexes {
            let value = self.get(index);
            if value >= x {
                answer += value;
            }
        }
        return answer;
    } // end of method

    /// 区間 [l, r) の max(0, value) の合計を返す
    /// value == 0 は足しても変わらないので, value >= 0 の合計として計算
    pub fn sum_max_zero(&self, l: usize, r: usize) -> i64 {
        return self.sum_greater_equal(l, r, 0);
    } // end of method
} // end of impl LazySortedSqrt 
